<?php
require_once __DIR__.'/attendance_analytics.php';
$yearId=(int)($_GET['school_year_id']??0); $now=new DateTimeImmutable('now',new DateTimeZone('Asia/Manila'));
if(!$yearId) $yearId=(int)getActiveSchoolYear($db)['id'];
[$scope,$bindings]=enrollmentSectionScope('sec',currentUser(),true);
$q=$db->prepare("SELECT DISTINCT y.id,y.label,y.starts_on,y.ends_on FROM school_years y JOIN sections sec ON sec.school_year_id=y.id WHERE ($scope) ORDER BY y.starts_on DESC"); $q->execute($bindings); $years=$q->fetchAll(); $selected=null;
foreach($years as $y) if((int)$y['id']===$yearId) $selected=$y;
if(!$selected) {http_response_code(403);exit('School-year access denied.');}
$defaultDate=min(max($now->format('Y-m-d'),$selected['starts_on']),$selected['ends_on']);
$month=(int)($_GET['month']??substr($defaultDate,5,2)); $calendarYear=(int)($_GET['year']??substr($defaultDate,0,4)); $sectionId=(int)($_GET['section']??0);
$sections=enrollmentReportSections($db,currentUser(),$yearId); $data=null; $error=null;
try {$data=loadMonthlyAttendanceAnalytics($db,currentUser(),$yearId,$calendarYear,$month,$sectionId?:null,$now);}
catch(DomainException|InvalidArgumentException $e){$error=$e->getMessage();http_response_code(400);}
$pageTitle='Monthly Attendance Analytics'; include __DIR__.'/header.php'; include __DIR__.'/sidebar.php';
?>
<div class="page-header"><div><h1 class="page-title">Monthly Attendance Overview<?= $data?' — '.sanitize(date('F Y',strtotime($data['period']['from']))):'' ?></h1><p class="page-subtitle">Daily learner counts and monthly day equivalents, with unresolved records shown separately.</p></div></div>
<form method="get" class="row g-2 mb-4"><div class="col-md-3"><label>School year</label><select class="form-select" name="school_year_id"><?php foreach($years as $y): ?><option value="<?= (int)$y['id'] ?>" <?= (int)$y['id']===$yearId?'selected':'' ?>><?= sanitize($y['label']) ?></option><?php endforeach; ?></select></div><div class="col-md-2"><label>Month</label><select class="form-select" name="month"><?php foreach(range(1,12) as $m): ?><option value="<?= $m ?>" <?= $month===$m?'selected':'' ?>><?= date('F',mktime(0,0,0,$m,1)) ?></option><?php endforeach; ?></select></div><div class="col-md-2"><label>Calendar year</label><input name="year" type="number" class="form-control" value="<?= $calendarYear ?>" min="1900" max="2100"></div><div class="col-md-3"><label>Section</label><select name="section" class="form-select"><option value="0">All authorized sections</option><?php foreach($sections as $s): ?><option value="<?= (int)$s['id'] ?>" <?= (int)$s['id']===$sectionId?'selected':'' ?>><?= sanitize($s['grade_level'].' — '.$s['section_name']) ?></option><?php endforeach; ?></select></div><div class="col-md-2 align-self-end"><button class="btn btn-primary">Apply</button></div></form>
<?php if($error): ?><div class="alert alert-warning"><?= sanitize($error) ?></div><?php endif; ?>
<?php if($data): $summary=$data['summary']; ?>
<div class="row g-3 mb-3"><?php foreach(['Distinct learners'=>$summary['learners'],'Eligible elapsed learner-days'=>$summary['eligible_days'],'Present day equivalents'=>$summary['present_units'],'Absent day equivalents'=>$summary['absent_units'],'Unresolved learner-days'=>$summary['unresolved_days'],'Attendance rate'=>$summary['attendance_rate']===null?'N/A':$summary['attendance_rate'].'%','Completion coverage'=>$summary['coverage']===null?'N/A':$summary['coverage'].'%'] as $label=>$value): ?><div class="col-md-3"><div class="card h-100"><div class="card-body"><div class="text-muted"><?= $label ?></div><strong><?= sanitize((string)$value) ?></strong></div></div></div><?php endforeach; ?></div>
<p class="small text-muted">Attendance rate = confirmed present day equivalents ÷ eligible elapsed learner-days. Partial attendance contributes 0.5 day. Excused days are absences; pending, review-needed and unrecorded days remain unresolved. Future dates and no-class dates are excluded. These operational metrics do not replace official school-form formulas.</p>
<div class="card mb-3"><div class="card-body"><h2 class="h5">Daily Attendance Breakdown</h2><div style="height:320px"><canvas id="panelDailyChart" aria-label="Daily attendance counts by date" role="img"></canvas></div></div></div>
<div class="card mb-3"><div class="table-responsive"><table class="table"><thead><tr><th>Date</th><?php foreach(array_slice(attendanceDecisionLabels(),0,9,true) as $label): ?><th><?= sanitize($label) ?></th><?php endforeach; ?><th>Attendance rate (%)</th></tr></thead><tbody><?php foreach($data['daily'] as $date=>$daily): ?><tr><td><a href="../attendance/attendance.php?<?= sanitize(http_build_query(['date'=>$date,'section'=>$sectionId,'school_year_id'=>$yearId])) ?>"><?= sanitize($date) ?></a><?= $daily['future']?' (future)':(!$daily['eligible_days']?' (no eligible days)':'') ?></td><?php foreach(array_slice(attendanceDecisionLabels(),0,9,true) as $status=>$label): ?><td><?= $daily['future']?'—':(int)$daily['counts'][$status] ?></td><?php endforeach; ?><td><?= $daily['attendance_rate']===null?'N/A':$daily['attendance_rate'].'%' ?></td></tr><?php endforeach; ?></tbody></table></div></div>
<div class="row g-3"><?php foreach($data['by_mode'] as $mode=>$metrics): ?><div class="col-md-4"><div class="card"><div class="card-body"><h2 class="h5"><?= deliveryLabels()[$mode] ?></h2><p><?= $metrics['eligible_days'] ?> learner-days · <?= $metrics['unresolved_days'] ?> unresolved</p></div></div></div><?php endforeach; ?></div>
<script>
document.addEventListener('DOMContentLoaded',()=>{if(typeof Chart==='undefined')return;const daily=<?= json_encode($data['daily'],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>;const labels=<?= json_encode(array_slice(attendanceDecisionLabels(),0,9,true)) ?>;new Chart(document.getElementById('panelDailyChart'),{type:'bar',data:{labels:Object.keys(daily),datasets:Object.entries(labels).map(([key,label],i)=>({label,data:Object.values(daily).map(d=>d.future?null:d.counts[key]),backgroundColor:['#16a34a','#ca8a04','#0ea5e9','#dc2626','#a855f7','#94a3b8','#ea580c','#64748b','#cbd5e1'][i]}))},options:{responsive:true,maintainAspectRatio:false,scales:{x:{stacked:true,title:{display:true,text:'Date'}},y:{stacked:true,beginAtZero:true,ticks:{precision:0},title:{display:true,text:'Learners'}}}}});});
</script>
<?php endif; include __DIR__.'/footer.php'; ?>
